        n = len(grid)

        # Function to collect elements along a diagonal with sum (i + j) = d
        def get_diagonal_elements(d):
            elements = []
            i, j = 0, d
            while i < n and j >= 0:
                elements.append(grid[i][j])
                i += 1
                j -= 1
            return elements

        # Collect all diagonals for bottom-left triangle (i + j <= n-1)
        bottom_left_diagonals = []
        for d in range(0, 2 * n - 1):
