class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        if n == 1:
            return grid

        # Step 1: Group elements by their diagonal key (i - j)
        diagonals = {}

        for i in range(n):
            for j in range(n):
                key = i - j
                if key not in diagonals:
                    diagonals[key] = []
                diagonals[key].append((i, j, grid[i][j]))

        # Step 2: Sort the diagonals as required
        for key in diagonals:
            elements = diagonals[key]
            # Determine the direction to sort
            if key <= 0:  # Bottom-left triangle (including middle diagonal)
                elements.sort(key=lambda x: -x[2])  # Non-increasing
            else:  # Top-right triangle
                elements.sort(key=lambda x: x[2])  # Non-decreasing

        # Step 3: Put the elements back into the grid
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                key = i - j
                if key not in diagonals:
                    continue
                # Collect all elements for this diagonal
                elements = diagonals[key]
                # Sort the elements again to ensure correct placement
                # This step is redundant, but we need to make sure we assign in order
                # To ensure that the same diagonal is processed in the correct order
                # (since the elements list may have been modified)
                elements.sort(key=lambda x: (x[0], x[1]))  # by row, then column
                for idx, (row, col, val) in enumerate(elements):
                    result[row][col] = val

        return result

