    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        from collections import defaultdict, deque
        import heapq

        # Initialize user status: online = True, offline time = -1 (not offline)
        user_status = [-1] * numberOfUsers  # -1 means online
        # A priority queue (min-heap) to track when users come back online
        offline_queue = []

        # Sort events by timestamp
        events.sort(key=lambda x: int(x[1]))

