            elif ord(original) == ord('z') and target == 'y':
                return 1
            elif abs(ord(target) - ord(original)) == 1:
                return 1
            else:
                return abs(ord(target) - ord(original))  # can only change by 1 step

        # Generate all possible characters for each position
        chars = string.ascii_lowercase
        n = len(caption)

        # BFS approach to find the minimal cost to reach a valid good caption
        # Each state is a tuple of (current_string, cost, current_position)
        # We use BFS to find the minimum cost and lex smallest string

