            time, x, y = heapq.heappop(heap)

            # If reached destination, return the time
            if x == n - 1 and y == m - 1:
                return time

            # Skip if already found a better path to this cell
            if time > min_time[x][y]:
                continue

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m:
                    new_time = max(time + 1, moveTime[nx][ny])
                    if new_time < min_time[nx][ny]:
                        min_time[nx][ny] = new_time
                        heapq.heappush(heap, (new_time, nx, ny))

        return -1  # In case no path found (should not happen due to problem constraints)

