        # Sort fruits and baskets in ascending order
        fruits.sort()
        baskets.sort()

        n = len(fruits)
        used_baskets = [False] * len(baskets)
        unplaced_count = 0

        for fruit in fruits:
            # Try to find the first available basket with capacity >= fruit
            for i in range(len(baskets)):
                if not used_baskets[i] and baskets[i] >= fruit:
                    used_baskets[i] = True
                    break
            else:
                # No suitable basket found
                unplaced_count += 1

        return unplaced_count

