    def maxRectangleArea(self, xCoord: List[int], yCoord: List[int]) -> int:
        from collections import defaultdict

        # Map each point to a tuple (x, y)
        points = list(zip(xCoord, yCoord))
        point_set = set(points)

        # Get all unique x and y coordinates
        x_coords = sorted(set(xCoord))
        y_coords = sorted(set(yCoord))

        max_area = -1

        # Precompute a dictionary of x to set of y values present at that x
        x_to_ys = defaultdict(set)
        for x, y in points:
            x_to_ys[x].add(y)

        # Iterate over all possible combinations of x1, x2, y1, y2
        for i in range(len(x_coords)):
            for j in range(i + 1, len(x_coords)):
                x1, x2 = x_coords[i], x_coords[j]
                # Get all possible y pairs
                for k in range(len(y_coords)):
                    for l in range(k + 1, len(y_coords)):
                        y1, y2 = y_coords[k], y_coords[l]
                        # Check if all four corners exist
                        if (x1, y1) in point_set and (x1, y2) in point_set and (x2, y1) in point_set and (x2, y2) in point_set:
