    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_length = n + m - 1
        if m > total_length:
            return ""

        # If str2 is longer than the word, then impossible
        if m > total_length:
            return ""

        # Precompute str2 for faster access
        s2 = str2

        # Helper function: check if the current word is valid up to this point
        def is_valid(word):
            for i in range(n):
                start = i
                end = start + m
                if end > len(word):
                    return False
                substr = word[start:end]
                if str1[i] == 'T':
                    if substr != s2:
                        return False
                else:  # 'F'
                    if substr == s2:
                        return False
            return True

        # Try to build the lex smallest string
        from itertools import product
        import string

        def build_lex_min(start, word):
            if len(word) == total_length:
                return word if is_valid(word) else None

            min_word = None
            current_len = len(word)

            # Try all possible characters from 'a' to 'z'
            for c in string.ascii_lowercase:
                new_word = word + c
                # We need to ensure that the word is built properly
                # Only proceed if we can still fill the rest of the word
                # (i.e., the rest of the positions are not yet constrained)
                # Here, we assume that the constraints are built incrementally
                result = build_lex_min(start + 1, new_word)
                if result:
