    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])
        start = (0, 0)
        end = (m - 1, n - 1)

        # If the start or end cell is unsafe and is the only cell, check health
        if m == 1 and n == 1:
            return health >= 1 - grid[0][0]

        from collections import deque

        # Directions: up, right, down, left
        directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

        # BFS with state tracking: (x, y, current_health)
        queue = deque()
        queue.append((0, 0, health))  # Start from (0,0) with initial health

        visited = set()
        visited.add((0, 0))

        while queue:
            x, y, curr_health = queue.popleft()

            # Check if we reached the end
            if (x, y) == end:
                if curr_health >= 1:
                    return True
                else:
                    continue  # Try other paths

            # Try all directions
            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                # Check if the new position is valid
